// App.js
import React, { useEffect, useState } from 'react';
import { exchangeToken } from './services/api'; // Import the exchangeToken function

const App = () => {
  const [isAuthorized, setIsAuthorized] = useState(false);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const success = urlParams.get('success');
    const error = urlParams.get('error');

    if (success) {
      // On success, fetch the access token
      getAccessToken();
    } else if (error) {
      console.error('Authorization error:', error);
      alert('Authorization failed. Please try again.');
    }
  }, []);

  const getAccessToken = async () => {
    try {
      // Request to retrieve stored access token from backend
      const response = await exchangeToken(); // Replace this with the actual function you wrote to fetch the token
      setIsAuthorized(true);
      // You can also set the access token in the SpotifyWebApi instance here if needed
    } catch (error) {
      console.error('Error fetching access token:', error);
      alert('Could not fetch access token. Please try again.');
    }
  };

  return (
    <div>
      <h1>Welcome to Track Similarity App</h1>
      {isAuthorized ? (
        <p>You are now authorized to use Spotify features.</p>
      ) : (
        <button onClick={() => window.location.href = 'http://localhost:3001/login'}>
          Login with Spotify
        </button>
      )}
    </div>
  );
};

export default App;
